using System;
using System.IO;
using EchoStation.Echo;
using EchoStation.Player;
using EchoStation.Salvage;
using EchoStation.SalvageNext;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.UI;
namespace EchoStation.SalvageExpansion
{
    [DefaultExecutionOrder(-50)]
    public sealed class ExpansionGraphics:MonoBehaviour,IDisplayBackend
    {
        [SerializeField]RenderPipelineAsset[] profiles;[SerializeField]Volume focusVolume;RenderPipelineAsset priorDefault,priorQuality;int priorAA;bool bound,recapture,closing;string validationSettings;ExpansionWorld world;DisplayTransaction transaction;DisplaySettingsStore store;DisplaySelection draft;Text panel,status;GameObject canvas;IDisposable lease;VolumeProfile focusInstance;DepthOfField depth;readonly InteractionFocusState focus=new InteractionFocusState();
        public RecoveryQuality Quality{get;private set;}=RecoveryQuality.Medium;public DisplayTransaction Transaction=>transaction;public bool IsOpen=>canvas&&canvas.activeSelf;
        public void Configure(RenderPipelineAsset[] pipelines,Volume volume){profiles=pipelines;focusVolume=volume;}
        public void ConfigureValidationSettings(string folder){string root=Path.GetFullPath("Library/EchoStation/SalvageExpansion/Tests")+Path.DirectorySeparatorChar;string path=Path.GetFullPath(folder);if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase)||IsOpen||transaction!=null&&transaction.IsPending)throw new ArgumentException("Owned idle validation settings required.");validationSettings=path;if(transaction!=null){store=new DisplaySettingsStore(path);transaction=new DisplayTransaction(this,store);}}
        void Start(){world=GetComponent<ExpansionWorld>();if(profiles==null||profiles.Length!=3||Array.Exists(profiles,p=>!p))throw new InvalidOperationException("Three expansion profiles required.");priorDefault=GraphicsSettings.defaultRenderPipeline;priorQuality=QualitySettings.renderPipeline;priorAA=QualitySettings.antiAliasing;bound=true;SetQuality(RecoveryQuality.Medium);store=new DisplaySettingsStore(validationSettings??Path.Combine(Application.persistentDataPath,"SalvageExpansion"));transaction=new DisplayTransaction(this,store);if(!Application.isEditor&&store.TryRead(out var saved,out _))TryApply(saved,out _);if(focusVolume){focusInstance=focusVolume.profile;focusInstance.TryGet(out depth);focusVolume.weight=0;}GetComponent<ExpansionPersistence>().Restored+=Close;}
        public void SetQuality(RecoveryQuality q){if((uint)q>2)throw new ArgumentException();Quality=q;GraphicsSettings.defaultRenderPipeline=profiles[(int)q];QualitySettings.renderPipeline=profiles[(int)q];GameRuntimeOptions.UseLLM=false;}
        public DisplaySelection Capture()=>new DisplaySelection(Quality,Mathf.Max(640,Screen.width),Mathf.Max(480,Screen.height),Screen.fullScreenMode==FullScreenMode.Windowed?DisplayWindowMode.Windowed:Screen.fullScreenMode==FullScreenMode.ExclusiveFullScreen?DisplayWindowMode.Exclusive:DisplayWindowMode.Borderless);
        public bool TryApply(DisplaySelection value,out string error){error="";if(Application.isEditor){error="分辨率与全屏请在Windows版测试。";return false;}SetQuality(value.Quality);Screen.SetResolution(value.Width,value.Height,value.Mode==DisplayWindowMode.Windowed?FullScreenMode.Windowed:value.Mode==DisplayWindowMode.Exclusive?FullScreenMode.ExclusiveFullScreen:FullScreenMode.FullScreenWindow);return true;}
        public bool Open()
        {
            if(!world||world.Pause.Blocked||!world.ActionsAllowed||!world.Input.HasApplicationFocus)return false;draft=Capture();lease=world.Pause.Acquire();world.Input.SetPointerCaptured(false);
            if(!panel){panel=SalvageUi.Panel(transform,"ExpansionDisplay",1050,740,123);canvas=SalvageUi.CanvasOf(panel);canvas.AddComponent<GraphicRaycaster>();panel.gameObject.SetActive(false);var root=panel.transform.parent;SalvageWidgets.Label(SalvageWidgets.Rect("Title",root,28,20,990,50),"画质与显示 [F10]",30);string[] names={"低画质","中画质","高画质"};for(int i=0;i<3;i++){int n=i;SalvageWidgets.Button(root,"Quality"+i,names[i],28+i*330,100,310,()=>{draft=new DisplaySelection((RecoveryQuality)n,draft.Width,draft.Height,draft.Mode);Refresh();});}int[] widths={1280,1600,1920},heights={720,900,1080};for(int i=0;i<3;i++){int n=i;SalvageWidgets.Button(root,"Size"+i,widths[i]+" × "+heights[i],28+i*330,180,310,()=>{draft=new DisplaySelection(draft.Quality,widths[n],heights[n],draft.Mode);Refresh();});}string[] modes={"窗口","无边框全屏","独占全屏"};for(int i=0;i<3;i++){int n=i;SalvageWidgets.Button(root,"Mode"+i,modes[i],28+i*330,260,310,()=>{draft=new DisplaySelection(draft.Quality,draft.Width,draft.Height,(DisplayWindowMode)n);Refresh();});}status=SalvageWidgets.Label(SalvageWidgets.Rect("Status",root,28,350,990,160),"",24);SalvageWidgets.Button(root,"Apply","应用",28,540,310,()=>{transaction.Begin(draft,Time.realtimeSinceStartupAsDouble);Refresh();});SalvageWidgets.Button(root,"Confirm","保留设置",358,540,310,()=>{transaction.Confirm(Time.realtimeSinceStartupAsDouble,world.Input.HasApplicationFocus);Refresh();});SalvageWidgets.Button(root,"Revert","还原",688,540,310,()=>{transaction.Cancel(Time.realtimeSinceStartupAsDouble);Refresh();});SalvageWidgets.Label(SalvageWidgets.Rect("AI",root,28,620,990,44),"UseLLM：关闭 · 模型尚未通过质量门禁，本版为脚本协作",22);SalvageWidgets.Button(root,"Close","返回 [Esc]",28,680,310,Close);}canvas.SetActive(true);Refresh();return true;
        }
        void Refresh(){if(status&&draft!=null)status.text="选择："+draft.Quality+" · "+draft.Width+"×"+draft.Height+" · "+draft.Mode+"\n"+transaction.Message+(transaction.Phase==DisplayPhase.Confirming?"\n剩余确认时间："+Math.Ceiling(transaction.SecondsLeft(Time.realtimeSinceStartupAsDouble))+"秒":"");}
        public void Close(){if(transaction!=null&&transaction.IsPending){closing=true;transaction.Cancel(Time.realtimeSinceStartupAsDouble);return;}closing=false;if(canvas)canvas.SetActive(false);lease?.Dispose();lease=null;recapture=true;}
        void Update(){if(transaction==null||!world.Input)return;transaction.Tick(Time.realtimeSinceStartupAsDouble,world.Input.HasApplicationFocus);if(IsOpen){Refresh();if(!world.Input.HasApplicationFocus||closing&&!transaction.IsPending)Close();}var k=Keyboard.current;if(k==null||!world.Input.HasApplicationFocus)return;if(k.f10Key.wasPressedThisFrame){if(IsOpen)Close();else Open();}else if(IsOpen&&k.escapeKey.wasPressedThisFrame)Close();}
        void LateUpdate(){if(recapture){recapture=false;world.Pause.RestorePointer();}if(depth){float? distance=null;if(Quality!=RecoveryQuality.Low&&world.Input.CanPlay&&world.TryRay(out var hit)&&(hit.collider.GetComponentInParent<ExpansionItemActor>()||hit.collider.GetComponentInParent<FacilityDevice>()))distance=hit.distance;focus.Step(distance,Mathf.Min(Time.unscaledDeltaTime,.1f));depth.gaussianStart.value=focus.Distance+.75f;depth.gaussianEnd.value=focus.Distance+4.5f;focusVolume.weight=focus.Weight;}}
        void OnDisable(){lease?.Dispose();lease=null;if(canvas)canvas.SetActive(false);if(bound){if(Array.IndexOf(profiles,GraphicsSettings.defaultRenderPipeline)>=0)GraphicsSettings.defaultRenderPipeline=priorDefault;if(Array.IndexOf(profiles,QualitySettings.renderPipeline)>=0)QualitySettings.renderPipeline=priorQuality;QualitySettings.antiAliasing=priorAA;bound=false;}}
        void OnDestroy(){var save=GetComponent<ExpansionPersistence>();if(save)save.Restored-=Close;if(focusInstance){foreach(var component in focusInstance.components)if(component)Destroy(component);Destroy(focusInstance);}}
    }
}
